contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address to, uint256 amount) public {
        // Claim airdrop once: fresh contract, caller not blacklisted, distribution not finished.
        c.getTokens();

        uint256 myBalance = c.balanceOf(address(this));
        require(amount <= myBalance);

        uint256 recipientBefore = c.balanceOf(to);

        bool ok = c.transfer(to, amount);

        uint256 myAfter = c.balanceOf(address(this));
        uint256 recipientAfter = c.balanceOf(to);

        assert(
            ok &&
            myBalance == 1000000000000000000000 &&
            c.blacklist(address(this)) &&
            myAfter + amount == myBalance &&
            recipientAfter + amount == recipientBefore + amount
        );
    }

    receive() external payable {}
}

