contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amt, address to) public {
        require(amt > 0);
        require(to != address(0));
        c.XBornID();
        require(!c.distributionFinished());
        require(c.totalRemaining() >= c.value());
        c.getTokens();
        uint balBefore = c.balanceOf(address(this));
        require(balBefore >= amt);
        c.approve(address(this), amt);
        require(c.allowance(address(this), address(this)) == amt);
        c.transferFrom(address(this), to, amt);
        assert(
            c.balanceOf(address(this)) == balBefore - amt &&
            c.balanceOf(to) == amt &&
            c.allowance(address(this), address(this)) == amt
        );
    }
